import axios from 'axios';
import { API_CONFIG } from '@/config/config';

export const chatModule = {
  namespaced: true,
  state: {
    recentChats: [],    // 所有最近聊天（按时间排序）
    recentGroups: [],   // 最近群聊
    recentUsers: []     // 最近单聊
  },
  mutations: {
    // 添加或更新最近聊天（自动区分群聊和单聊）
    ADD_RECENT_CHAT(state, chat) {
      // 转换ID为数字类型（处理可能的字符串ID）
      const chatId = typeof chat.id === 'string' ? parseInt(chat.id, 10) : chat.id;
      
      // 区分群聊和单聊
      const isGroup = chat.isGroup === true;
      
      // 处理群聊
      if (isGroup) {
        const existingIndex = state.recentGroups.findIndex(g => 
          typeof g.id === 'string' 
            ? parseInt(g.id, 10) === chatId 
            : g.id === chatId
        );
        
        if (existingIndex !== -1) {
          state.recentGroups.splice(existingIndex, 1);
        }
        
        state.recentGroups.unshift({ ...chat, id: chatId });
        
        // 限制列表长度
        if (state.recentGroups.length > 50) {
          state.recentGroups.pop();
        }
      } 
      // 处理单聊
      else {
        const existingIndex = state.recentUsers.findIndex(u => 
          typeof u.id === 'string' 
            ? parseInt(u.id, 10) === chatId 
            : u.id === chatId
        );
        
        if (existingIndex !== -1) {
          state.recentUsers.splice(existingIndex, 1);
        }
        
        state.recentUsers.unshift({ ...chat, id: chatId });
        
        // 限制列表长度
        if (state.recentUsers.length > 50) {
          state.recentUsers.pop();
        }
      }
      
      // 更新统一的最近聊天列表（按时间排序）
      const allChats = [...state.recentGroups, ...state.recentUsers];
      allChats.sort((a, b) => {
        const timeA = a.lastMessageTime ? new Date(a.lastMessageTime) : new Date(0);
        const timeB = b.lastMessageTime ? new Date(b.lastMessageTime) : new Date(0);
        return timeB - timeA;
      });
      
      state.recentChats = allChats.slice(0, 50);
    },
    
    // 初始化最近聊天（从数据库加载）
    INIT_RECENT_CHATS(state, chats) {
      // 转换所有ID为数字类型
      const normalizedChats = chats.map(chat => {
        const id = typeof chat.id === 'string' ? parseInt(chat.id, 10) : chat.id;
        return { ...chat, id };
      });
      
      // 区分群聊和单聊
      const groups = normalizedChats.filter(chat => chat.isGroup === true);
      const users = normalizedChats.filter(chat => chat.isGroup !== true);
      
      // 去重并排序
      state.recentGroups = groups;
      state.recentUsers = users;
      
      // 更新统一的最近聊天列表
      const allChats = [...groups, ...users];
      allChats.sort((a, b) => {
        const timeA = a.lastMessageTime ? new Date(a.lastMessageTime) : new Date(0);
        const timeB = b.lastMessageTime ? new Date(b.lastMessageTime) : new Date(0);
        return timeB - timeA;
      });
      
      state.recentChats = allChats;
    },
    
    // 单独添加群聊
    ADD_GROUP_RECENT_CHAT(state, group) {
      // 转换ID为数字类型
      const groupId = typeof group.id === 'string' ? parseInt(group.id, 10) : group.id;
      
      const existingIndex = state.recentGroups.findIndex(g => 
        typeof g.id === 'string' 
          ? parseInt(g.id, 10) === groupId 
          : g.id === groupId
      );
      
      if (existingIndex !== -1) {
        state.recentGroups.splice(existingIndex, 1);
      }
      
      state.recentGroups.unshift({ ...group, id: groupId });
      
      // 限制列表长度
      if (state.recentGroups.length > 50) {
        state.recentGroups.pop();
      }
      
      // 更新统一列表
      const allChats = [...state.recentGroups, ...state.recentUsers];
      allChats.sort((a, b) => {
        const timeA = a.lastMessageTime ? new Date(a.lastMessageTime) : new Date(0);
        const timeB = b.lastMessageTime ? new Date(b.lastMessageTime) : new Date(0);
        return timeB - timeA;
      });
      
      state.recentChats = allChats.slice(0, 50);
    },
    
    // 单独添加单聊
    ADD_USER_RECENT_CHAT(state, user) {
      // 转换ID为数字类型
      const userId = typeof user.id === 'string' ? parseInt(user.id, 10) : user.id;
      
      const existingIndex = state.recentUsers.findIndex(u => 
        typeof u.id === 'string' 
          ? parseInt(u.id, 10) === userId 
          : u.id === userId
      );
      
      if (existingIndex !== -1) {
        state.recentUsers.splice(existingIndex, 1);
      }
      
      state.recentUsers.unshift({ ...user, id: userId });
      
      // 限制列表长度
      if (state.recentUsers.length > 50) {
        state.recentUsers.pop();
      }
      
      // 更新统一列表
      const allChats = [...state.recentGroups, ...state.recentUsers];
      allChats.sort((a, b) => {
        const timeA = a.lastMessageTime ? new Date(a.lastMessageTime) : new Date(0);
        const timeB = b.lastMessageTime ? new Date(b.lastMessageTime) : new Date(0);
        return timeB - timeA;
      });
      
      state.recentChats = allChats.slice(0, 50);
    },
    
    // 清除所有最近聊天
    CLEAR_RECENT_CHATS(state) {
      state.recentChats = [];
      state.recentGroups = [];
      state.recentUsers = [];
    },
    
    // 更新聊天的未读计数
    UPDATE_UNREAD_COUNT(state, { targetId, count }) {
      const targetIdNum = typeof targetId === 'string' ? parseInt(targetId, 10) : targetId;
      
      // 在群聊中查找
      const groupIndex = state.recentGroups.findIndex(g => g.id === targetIdNum);
      if (groupIndex !== -1) {
        state.recentGroups[groupIndex].unreadCount = count;
      }
      
      // 在单聊中查找
      const userIndex = state.recentUsers.findIndex(u => u.id === targetIdNum);
      if (userIndex !== -1) {
        state.recentUsers[userIndex].unreadCount = count;
      }
      
      // 更新统一列表
      const allChats = [...state.recentGroups, ...state.recentUsers];
      state.recentChats = allChats;
    }
  },
  actions: {
    // 从数据库加载最近聊天列表
    async loadRecentChats({ commit, rootState }) {
      try {
        const userId = rootState.user.id;
        const response = await axios.get(`${API_CONFIG.BASE_URL}/ws/chat/recent-chats/${userId}`, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
        
        // 转换API返回的数据格式以匹配前端期望
        const formattedChats = response.data.map(chat => ({
          id: chat.target_id,
          username: chat.target_username,
          photo: chat.target_photo,
          lastMessage: chat.last_message,
          lastMessageTime: chat.last_message_time,
          unreadCount: chat.unread_count || 0,
          isGroup: chat.is_group || false // 确保包含isGroup字段
        }));
        
        commit('INIT_RECENT_CHATS', formattedChats);
        return formattedChats;
      } catch (error) {
        console.error('加载最近聊天列表失败:', error);
        return [];
      }
    },
    
    // 保存最近聊天到数据库（区分群聊和单聊）
    async saveRecentChat({ rootState }, chatInfo) {
      try {
        // 检查用户是否已登录
        if (!rootState.user || !rootState.user.id) {
          console.log('用户未登录，无法保存最近聊天记录');
          return;
        }
        
        // 检查 chatInfo 是否存在
        if (!chatInfo) {
          console.error('saveRecentChat 错误：未提供聊天用户信息');
          return;
        }
        
        const userId = rootState.user.id;
        const isGroup = chatInfo.isGroup === true;
        
        const recentChatData = {
          user_id: userId,
          target_id: chatInfo.id,
          target_username: chatInfo.username,
          target_photo: chatInfo.photo,
          last_message: chatInfo.lastMessage || '',
          last_message_time: chatInfo.lastMessageTime || new Date().toISOString(),
          unread_count: chatInfo.unreadCount || 0,
          is_group: isGroup
        };
        
        await axios.post(`${API_CONFIG.BASE_URL}/ws/chat/recent-chats`, recentChatData, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
      } catch (error) {
        console.error('保存最近聊天记录失败:', error);
        throw error;
      }
    },
    
    // 保存群聊信息
    async saveGroupRecentChat({ dispatch }, groupInfo) {
      // 添加isGroup标识
      const groupData = {
        ...groupInfo,
        isGroup: true
      };
      
      // 使用统一的保存方法
      return dispatch('saveRecentChat', groupData);
    },
    
    // 保存单聊信息
    async saveUserRecentChat({ dispatch }, userInfo) {
      // 添加isGroup标识
      const userData = {
        ...userInfo,
        isGroup: false
      };
      
      // 使用统一的保存方法
      return dispatch('saveRecentChat', userData);
    },
    
    // 清除未读计数
    async clearUnreadCount({ commit, rootState }, targetId) {
      try {
        const userId = rootState.user.id;
        await axios.post(`${API_CONFIG.BASE_URL}/ws/chat/recent-chats/${userId}/clear-unread/${targetId}`, {}, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
        
        // 本地更新未读计数为0
        commit('UPDATE_UNREAD_COUNT', { targetId, count: 0 });
      } catch (error) {
        console.error('清除未读计数失败:', error);
        throw error;
      }
    },
    
    // 批量更新未读计数
    async updateUnreadCounts({ commit, rootState }, countsMap) {
      try {
        const userId = rootState.user.id;
        
        // 批量更新服务器上的未读计数
        await axios.post(`${API_CONFIG.BASE_URL}/ws/chat/recent-chats/${userId}/update-unreads`, countsMap, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
        
        // 本地更新未读计数
        Object.entries(countsMap).forEach(([targetId, count]) => {
          commit('UPDATE_UNREAD_COUNT', { targetId, count });
        });
      } catch (error) {
        console.error('批量更新未读计数失败:', error);
        throw error;
      }
    },
    
    // 登出时清除所有聊天记录
    async clearAllChats({ commit }) {
      commit('CLEAR_RECENT_CHATS');
    }
  },
  getters: {
    getRecentChats: state => state.recentChats,
    getRecentGroups: state => state.recentGroups,
    getRecentUsers: state => state.recentUsers,
    
